// Direct Module Federation configuration for the OneCX shell, reconstructed by hand for use
// with `@module-federation/enhanced/rspack` (the `@nx/angular/module-federation`
// `withModuleFederation` wrapper is not used).
//
// `name` is the MF container name and MUST equal the project name normalized with
// `normalizeProjectName`, because the shell looks its own federation instance up by that name
// at runtime (see `src/app/about/componenets/about.component.ts` → `i.name === 'onecx_shell_ui'`).
//
// `getShared()` reproduces the shared dependency set that the wrapper generated by combining the
// project's direct npm dependencies with the OneCX shared recommendations
// (`@onecx/accelerator`'s `getOneCXSharedRecommendations`).
import {
  getDependentPackagesForProject,
  applySharedFunction,
  normalizeProjectName,
  sharePackages
} from '@nx/module-federation'
import { getOneCXSharedRecommendations } from '@onecx/accelerator'
import { createProjectGraphAsync, readCachedProjectGraph } from '@nx/devkit'

const PROJECT_NAME = 'onecx-shell-ui'

// Angular core packages are always shared (mirrors the wrapper's DEFAULT_ANGULAR).
const DEFAULT_ANGULAR = ['@angular/core', '@angular/animations', '@angular/common']

// Packages that must never be hoisted into the shared scope.
const AVOID_SHARED = ['zone.js', '@nx/angular/mf', '@nrwl/angular/mf', '@nx/angular-rspack']

export const name = normalizeProjectName(PROJECT_NAME)
export const shareScope = 'angular_21'
// Rspack emits the ESM federation entry as `remoteEntry.js` (not the webpack wrapper's `.mjs`).
export const filename = 'remoteEntry.js'
export const exposes = {
  './OneCXShellToastComponent': 'src/app/remotes/shell-toast/shell-toast.component.main.ts'
}
export const library = { type: 'module' } as const

async function getProjectGraph() {
  try {
    return readCachedProjectGraph()
  } catch {
    return createProjectGraphAsync()
  }
}

/**
 * Build the MF `shared` map: the project's direct npm dependencies (minus `AVOID_SHARED`), merged
 * with the Angular core defaults, each filtered and configured through
 * `getOneCXSharedRecommendations` — the same behavior the deprecated wrapper produced.
 */
export async function getShared() {
  const graph = await getProjectGraph()
  const { npmPackages } = getDependentPackagesForProject(graph, PROJECT_NAME)

  let packages = Array.from(new Set([...DEFAULT_ANGULAR, ...npmPackages.filter((p) => !AVOID_SHARED.includes(p))]))
  packages = packages.filter((pkg) => {
    try {
      return getOneCXSharedRecommendations(pkg, {}) !== false
    } catch {
      return true
    }
  })

  const shared = sharePackages(packages)
  for (const pkg of AVOID_SHARED) {
    delete shared[pkg]
  }
  const sharedDeps = { ...shared }
  applySharedFunction(sharedDeps, (libraryName, sharedConfig) =>
    getOneCXSharedRecommendations(libraryName, sharedConfig)
  )
  return sharedDeps
}
